// Чтение: кэш сбоку. Время жизни с разбросом, чтобы ключи не истекали синхронно.
Obj o = cache.get(id);
if (o == null) {
    o = db.find(id);
    cache.set(id, o, ttl + random(0, ttl / 4));
}
return o;

// Запись: удалять ключ, а не перезаписывать —
// иначе параллельный читатель может положить поверх устаревшее значение.
db.update(id, patch);
cache.delete(id);

begin;
  -- ключ и бизнес-эффект пишем одной транзакцией
  insert into processed(idempotency_key) values (?)
    on conflict do nothing returning 1;
  -- если returning пуст — операцию уже выполняли: возвращаем сохранённый ответ
  insert into payments(order_id, amount) values (?, ?);
commit;
